// @generated by luaudocs. Do not edit; regenerated by every build.
//
// Pre-parse markdown rewrites installed as a single markdown-it core rule by
// the generated config.mts. Two provide Docusaurus compatibility (`:::note`
// admonitions become VitePress containers, and `<Tabs>` / `<TabItem>` groups
// become the tab strip markup that `::: code-group` renders); `<Frame>` is
// LuauDocs's own callout frame. The same rule prepends each page's breadcrumb
// trail before block parsing.
//
// All rewrites share a single fence-masking pass so fenced code examples that
// show `<Frame>`, `<Tabs>`, or `:::note` syntax are left untouched.
//
// Because this file is synced into user sites, it cannot import from `src/`;
// `splitFences` lives here and `src/markdown.ts` re-exports it.
import type MarkdownIt from "markdown-it";

// Up-to-3-space indent accepted by CommonMark, followed by a fence marker run.
const FENCE_OPENER = /^[ \t]{0,3}(`{3,}|~{3,})/;

/**
 * Splits markdown into segments alternating between prose (even indices) and
 * fenced code blocks (odd indices) so rewrites leave fenced code verbatim. A
 * fence closes only on a marker of the same character at least as long as the
 * opener with nothing trailing on the line. An unterminated fence runs to the
 * end of the string.
 *
 * Enforces CommonMark's 3-space indentation cap on fence openers so a
 * 4-space-indented code block showing a fence cannot flip the parity of later
 * segments.
 */
export function splitFences(text: string): string[] {
	if (!text.includes("```") && !text.includes("~~~")) {
		return [text];
	}
	const parts: string[] = [];
	let start = 0;
	let offset = 0;
	let fence: string | undefined;
	for (const line of text.split(/(?<=\n)/)) {
		const marker = FENCE_OPENER.exec(line)?.[1];
		if (!fence && marker) {
			parts.push(text.slice(start, offset));
			start = offset;
			fence = marker;
		} else if (
			fence &&
			marker?.startsWith(fence) &&
			line.slice(line.indexOf(marker) + marker.length).trim() === ""
		) {
			parts.push(text.slice(start, offset + line.length));
			start = offset + line.length;
			fence = undefined;
		}
		offset += line.length;
	}
	parts.push(text.slice(start));
	return parts;
}

/** Escapes HTML special characters for element text and double-quoted attributes. */
export function escapeHtml(text: string): string {
	return text
		.replace(/&/g, "&amp;")
		.replace(/</g, "&lt;")
		.replace(/>/g, "&gt;")
		.replace(/"/g, "&quot;");
}

/**
 * Backslash-escapes inline markdown punctuation so identifiers like `_x_` or
 * `<T>` render literally rather than as emphasis or HTML tags. `markdown-it`
 * strips backslash escapes before computing heading slugs, so escaping a heading
 * title does not change its anchor.
 */
export function escapeMarkdown(text: string): string {
	return text.replace(/[\\`*_[\]<>{}!#~&:|]/g, "\\$&");
}

/** Docusaurus admonition kinds -> VitePress container kinds. */
const ADMONITION_MAP: Record<string, string> = {
	note: "info",
	tip: "tip",
	info: "info",
	caution: "warning",
	warning: "warning",
	danger: "danger",
};

/**
 * Rewrites Docusaurus admonition openers (`:::note`, `:::caution`, and
 * Docusaurus 3's bracketed `:::tip[Title]`) into VitePress container openers
 * (`::: info`, `::: warning`, `::: tip Title`). Unknown container kinds and
 * closing `:::` lines pass through unchanged.
 */
function rewriteAdmonitions(text: string): string {
	return text.replace(
		/^([ \t]{0,3}):::(\w+)(.*)$/gm,
		(match, indent: string, kind: string, rest: string) => {
			const mapped = ADMONITION_MAP[kind.toLowerCase()];
			if (!mapped) {
				return match;
			}
			const title = rest.match(/^\[([^\]]*)\][ \t\r]*$/);
			return `${indent}::: ${mapped}${title ? ` ${title[1]}` : rest}`;
		},
	);
}

/** Component tags handled by `rewriteMarkup`, exported for the Moonwave converter's report. */
export const REWRITTEN_COMPONENTS = ["Tabs", "TabItem", "Frame"] as const;

/** Matches a block-level JSX element whose opening and closing tags sit on their
 * own lines (group 1: attributes, group 2: inner body). */
function blockElement(tag: string): RegExp {
	return new RegExp(
		`^[ \\t]{0,3}<${tag}\\b([^>]*)>[ \\t]*\\r?\\n([\\s\\S]*?)^[ \\t]*<\\/${tag}>[ \\t]*$`,
		"gm",
	);
}

const TAB_GROUP = blockElement("Tabs");
const TAB_ITEM = /<TabItem\b([^>]*)>([\s\S]*?)<\/TabItem>/g;
// Null-byte sentinel used to mask fenced code blocks during component matching.
const MARK = "\u0000";
const MASKED_FENCE = new RegExp(`^${MARK}(\\d+)${MARK}$`);
const MASKED_FENCES = new RegExp(`${MARK}(\\d+)${MARK}`, "g");
// The opening line of a fenced code block (where VitePress reads `active`).
const FENCE_INFO = new RegExp(`${FENCE_OPENER.source}[^\\n]*`);
// A VitePress fence title (`[init.luau]`) on the fence opener line.
const FENCE_TITLE = /\s*\[(?:[^[\]]|\[[^[\]]*\])*\]/;

/** Returns the trailing newline separator before a closing HTML tag (a masked fence already carries its own trailing newline). */
function closeGap(body: string): string {
	return body.endsWith(MARK) ? "\n" : "\n\n";
}

/** Reads a double- or single-quoted attribute from an opening tag's attribute string. */
function attr(attrs: string, name: string): string | undefined {
	return attrs.match(new RegExp(`\\b${name}\\s*=\\s*(["'])(.*?)\\1`))?.[2];
}

/** Tests for Docusaurus's boolean `default` attribute on `<TabItem>` after stripping quoted attribute values. */
function isDefault(attrs: string): boolean {
	return /\bdefault\b/.test(attrs.replace(/(["']).*?\1/g, ""));
}

/**
 * Rewrites Docusaurus/Moonwave `<Tabs>` and `<TabItem>` blocks into the HTML
 * structure that VitePress's `::: code-group` container produces. Emitting the
 * container's HTML structure directly allows tabs to hold arbitrary prose and
 * multiple blocks while reusing VitePress's built-in tab styling and switching.
 */
function rewriteTabs(masked: string, fences: string[]): string {
	// Radio input `name` attributes must be unique per group on a page.
	let groups = 0;
	return masked.replace(TAB_GROUP, (group, _attrs: string, body: string) => {
		const items = [...body.matchAll(TAB_ITEM)].map(([, attrs = "", content = ""]) => {
			const text = content.trim();
			const marker = text.match(MASKED_FENCE);
			return {
				// Fall back to `value` when `label` is omitted, matching Docusaurus.
				label: attr(attrs, "label") ?? attr(attrs, "value") ?? "",
				default: isDefault(attrs),
				body: text,
				fence: marker ? fences[Number(marker[1])] : undefined,
			};
		});
		if (items.length === 0) {
			return group;
		}
		const top = Math.max(
			items.findIndex((item) => item.default),
			0,
		);
		const id = `tabs-${groups++}`;
		const strip = items
			.map((item, index) => {
				// Set `data-title` on the `<label>` so `vitepress-plugin-group-icons`
				// attaches the matching file-type or tool icon.
				const label = escapeHtml(item.label);
				return (
					`<input type="radio" name="${id}" id="${id}-${index}"${index === top ? " checked" : ""}>` +
					`<label data-title="${label}" for="${id}-${index}">${label}</label>`
				);
			})
			.join("");
		const panels = items.map((item, index) => {
			if (item.fence !== undefined) {
				// When a tab contains a single code fence, the fence itself is the
				// panel; strip any `[title]` from the fence opener since the tab
				// label already names it.
				const fence = item.fence.replace(FENCE_INFO, (line) => {
					const bare = line.replace(FENCE_TITLE, "");
					return index === top ? `${bare} active` : bare;
				});
				return fence.trimEnd();
			}
			return (
				`<div class="vp-block${index === top ? " active" : ""}">\n\n` +
				`${item.body}${closeGap(item.body)}</div>`
			);
		});
		// Keep blank lines around panels and closing `</div>` tags so `markdown-it`
		// parses the inner markdown rather than treating it as part of a raw HTML block.
		return (
			`<div class="vp-code-group"><div class="tabs">${strip}</div><div class="blocks">\n\n` +
			`${panels.join("\n\n")}\n\n</div></div>`
		);
	});
}

const FRAME = blockElement("Frame");

// Matches an ATX heading (`#` through `######`) with up to 3 leading spaces.
const ATX_HEADING = /^[ \t]{0,3}(#{1,6})[ \t]+(.+?)(?:[ \t]+#+)?[ \t]*$/gm;

// Matches inline constructs used in generated API headings: inline code spans,
// markdown links with optional `{.class}` attributes, and backslash escapes.
const HEADING_INLINE =
	/`([^`\n]+)`|\[([^\]\n]*)\]\((<[^<>\n]*>|[^\s()]*)\)(?:\{([^{}\n]*)\})?|\\([!-/:-@[-`{-~])/g;

/** Converts inline markdown constructs inside a framed heading into HTML. */
function headingHtml(text: string): string {
	return text.replace(
		HEADING_INLINE,
		(
			_match,
			code: string | undefined,
			label: string | undefined,
			href: string | undefined,
			attrs: string | undefined,
			escaped: string | undefined,
		) => {
			if (code !== undefined) {
				return `<code v-pre>${escapeHtml(code)}</code>`;
			}
			if (label !== undefined) {
				const classes = (attrs ?? "")
					.split(/\s+/)
					.filter((attr) => attr.startsWith("."))
					.map((attr) => attr.slice(1));
				const cls = classes.length > 0 ? ` class="${escapeHtml(classes.join(" "))}"` : "";
				const target = href!.replace(/^<(.*)>$/, "$1");
				return `<a href="${escapeHtml(target)}"${cls}>${headingHtml(label)}</a>`;
			}
			return escapeHtml(escaped!);
		},
	);
}

/**
 * Rewrites ATX headings inside a `<Frame>` body into raw `<hN>` tags without
 * `id` attributes. Because a `<Frame>` quotes content from another page (often
 * an embedded API section), its headings should not appear in the host page's
 * "On this page" outline or collide with the host page's heading anchors.
 *
 * Since raw `<hN>` tags bypass `markdown-it`'s inline parser, `headingHtml`
 * converts code spans, linked badges, and backslash escapes in the heading line
 * directly to HTML.
 */
function unlistHeadings(body: string): string {
	return body.replace(
		ATX_HEADING,
		(_line, hashes: string, text: string) =>
			`<h${hashes.length}>${headingHtml(text)}</h${hashes.length}>`,
	);
}

/**
 * Percent-encodes whitespace, quotes, angle brackets, backslashes, and backticks
 * so a URL is safe inside markdown link destinations and fence link tables.
 */
export function encodeHref(url: string): string {
	return url.replace(/[\s<>"\\`]/g, (char) => encodeURIComponent(char));
}

/**
 * Formats a URL as a safe markdown link destination, wrapping it in `<...>`
 * when it contains parentheses.
 */
export function linkDestination(url: string): string {
	const safe = encodeHref(url);
	return /[()]/.test(safe) ? `<${safe}>` : safe;
}

/**
 * Rewrites `<Frame>` into a bordered callout block with an optional top-border
 * caption (`label`, optionally linked via `link`).
 *
 * Linked captions and the frame body are emitted as markdown separated by blank
 * lines so VitePress prefixes the site `base`, runs its dead-link check, and
 * parses the body as markdown rather than raw HTML.
 */
function rewriteFrames(masked: string): string {
	return masked.replace(FRAME, (_frame, attrs: string, body: string) => {
		const label = attr(attrs, "label");
		const link = attr(attrs, "link");
		const caption =
			label === undefined
				? ""
				: link === undefined
					? `<div class="luaudocs-frame-label">${escapeHtml(label)}</div>\n`
					: `<div class="luaudocs-frame-label">\n\n[${escapeMarkdown(label)}` +
						`<span class="luaudocs-frame-arrow">&#8594;</span>](${linkDestination(link)})` +
						`\n\n</div>\n`;
		const content = unlistHeadings(body.trim());
		return `<div class="luaudocs-frame">\n${caption}\n${content}${closeGap(content)}</div>`;
	});
}

/**
 * Runs `<Tabs>`, `<Frame>`, and admonition rewrites over a markdown document
 * while masking fenced code blocks with null-byte markers so code examples are
 * never rewritten.
 */
export function rewriteMarkup(text: string): string {
	const tabs = text.includes("<Tabs");
	const frames = text.includes("<Frame");
	const admonitions = /^[ \t]{0,3}:::\w/m.test(text);
	if (!tabs && !frames && !admonitions) {
		return text;
	}
	const fences: string[] = [];
	const masked = splitFences(text)
		.map((part, index) => {
			if (index % 2 === 0) {
				return part;
			}
			// Keep the fence's trailing newline outside the marker so line-anchored
			// regexes still match on the line immediately following a code block.
			const newline = part.endsWith("\n") ? "\n" : "";
			const body = newline === "" ? part : part.slice(0, -1);
			return MARK + (fences.push(body) - 1) + MARK + newline;
		})
		.join("");
	let rewritten = masked;
	if (tabs) {
		rewritten = rewriteTabs(rewritten, fences);
	}
	if (frames) {
		rewritten = rewriteFrames(rewritten);
	}
	if (admonitions) {
		rewritten = rewriteAdmonitions(rewritten);
	}
	return rewritten.replace(MASKED_FENCES, (_marker, index: string) => fences[Number(index)]!);
}

/*
 * ------------------------------------------------------------------ page trail
 */

/** One breadcrumb step in a page's navigation trail (`link` is omitted for unindexed folders). */
export interface TrailSegment {
	text: string;
	link?: string;
}

/** Baked map of docs-relative markdown paths to breadcrumb trails. */
export type PageTrails = Record<string, TrailSegment[] | undefined>;

/**
 * Prepends a page's breadcrumb trail above its title. Emits markdown links
 * inside `<div class="luaudocs-trail">` (surrounded by blank lines) so VitePress
 * applies the site `base` and dead-link check, and places the trail before the
 * H1 heading so VitePress's local search indexer ignores it.
 */
export function prependTrail(source: string, trail: TrailSegment[] | undefined): string {
	if (trail === undefined || trail.length === 0) {
		return source;
	}
	const steps = trail
		.map((step) => (step.link === undefined ? step.text : `[${step.text}](${step.link})`))
		.join(" › ");
	return `<div class="luaudocs-trail">\n\n${steps}\n\n</div>\n\n${source}`;
}

/**
 * Installs the `markdown-it` core rule that runs `rewriteMarkup` and
 * `prependTrail` on each page's raw source before block parsing.
 */
export function installMarkupRule(md: MarkdownIt, trails: PageTrails): void {
	md.core.ruler.before("block", "luaudocs", (state) => {
		const page = (state.env as { relativePath?: string } | null)?.relativePath ?? "";
		state.src = prependTrail(rewriteMarkup(state.src), trails[page]);
		return true;
	});
}
